INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('circleci', 'CircleCI', 'circleci', 'Performance', 'audrey-confirmed', 'Official: 30,000 credits a month, then 15 USD per 25,000', 'connected-working', 'GitHub, Gitar and Slack per Audrey. Projects: revvel-standards, reese-reviews, amazon-books, forensicfinders. linear-a has none', NULL, 'Self-hosted runner: 20 concurrent tasks on Performance, no per-minute charge, so CARESSE can stand in for the billing-locked Actions minutes. Schedule triggers stand in for Actions cron', '2026-11-14', '2026-11-19', 1, 'The older TOOL_COST_INDEX row says free tier, 6,000 build minutes a month. Performance is Audrey''s word.', 10);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('circleci-slack', 'CircleCI to Slack', 'circleci-slack', 'Part of the CircleCI org', 'doc-verified', 'The docs state no separate fee', 'connected-working', 'Audrey, 2026-11-14', NULL, 'The app posts workflow results and lets you approve or cancel on-hold workflows from Slack. The docs do not describe starting a pipeline from Slack. To start one, post to the pipeline trigger API from n8n or a small custom Slack app', NULL, '2026-11-19', 0, NULL, 20);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('gitar', 'Gitar', 'gitar', 'A higher membership she associates with Sonar', 'unverified', 'Audrey''s word is a higher membership. Official tiers: Core, Pro, Enterprise. Exact tier unverified', 'connected-working', 'CircleCI connected and working (Audrey); others available', NULL, 'Keep deterministic checks in CircleCI jobs and use Gitar only for judgment calls. Scope settings limit what it processes', NULL, '2026-11-19', 0, NULL, 30);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('sonarqube-cloud', 'Sonar (SonarQube Cloud)', 'sonarqube-cloud', 'Unverified whether a separate subscription exists', 'unverified', 'Gitar is now a Sonar product but a Gitar plan is not documented as including SonarQube. Official Free: 50k lines of private code, 5 members', 'unverified', 'Checks have been seen on PRs', NULL, 'The free plan covers small private repos. Unlimited for public repos', NULL, '2026-11-19', 0, NULL, 40);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('cubic', 'Cubic', 'cubic', 'Team', 'audrey-confirmed', 'Official: 30 USD per developer a month, billed yearly', 'connected-working', 'As a GitHub reviewer and installed in Notion. Seat and line usage unverified', NULL, 'Free for public repos. Linear and Notion context in reviews replaces a separate requirements-check tool', '2026-11-14', '2026-11-19', 0, NULL, 50);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('chunk', 'Chunk', 'chunk', 'CircleCI beta, on Free, Performance and Scale', 'audrey-confirmed', 'Audrey says she has it. It is CircleCI''s, not Cubic''s', 'available', 'Org setup unverified', NULL, 'No extra fee during beta. Uses credits and model tokens, and becomes paid at general availability', '2026-11-14', '2026-11-19', 0, NULL, 60);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('bito', 'Bito', 'bito', 'Paid on 2026-11-11, plan and amount unknown', 'unverified', 'Audrey says she paid. Official: Team 12 to 15 USD, Professional 20 to 25 USD per seat a month', 'connected', 'GitHub App, `bito-ai.yml`. Plan unverified', NULL, 'Same job as Gitar and Cubic. Free plan gives PR summaries', NULL, '2026-11-19', 1, 'The older TOOL_COST_INDEX row says CUT 2026-07-08 (D006), 0 USD. Audrey paid on 2026-11-11. The cut and the payment are not reconciled.', 70);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('notion', 'Notion', 'mcp-notion', 'Unknown', 'unverified', 'One member, one teamspace, no plan field readable', 'connected', 'MCP connected. Bots installed: Composio, cubic, DEVIN_BRIDGE, Notion MCP', NULL, 'Notion AI connectors for Slack, GitHub and Linear need Business or Enterprise. n8n or the Notion API does the same on a free plan', NULL, '2026-11-19', 1, 'TOOLS_CATALOG row 68 says Free or 8 USD per user a month. Notion Plus is 10 USD per member a month.', 80);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('n8n', 'n8n', 'n8n', 'Community, self-hosted, free. Lab on Audrey''s computer, localhost only', 'unverified', 'Conflict: docs/standards/RUNNER_TARGETS.md says the operator pays about 60 USD a month for n8n and Gumloop together. Which is right is unconfirmed', 'unverified', 'Trial lab only', NULL, 'Replaces Zapier tasks and Notion''s Business-only GitHub sync. Notion webhooks need a public HTTPS endpoint', NULL, '2026-11-19', 1, 'Free self-hosted Community row conflicts with RUNNER_TARGETS.md (about 60 USD a month, n8n plus Gumloop).', 90);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('slack', 'Slack', 'mcp-slack', 'Unknown (oaudrey workspace)', 'unverified', NULL, 'connected-working', 'For CircleCI (Audrey) and MergeMe', NULL, 'The CircleCI docs state no fee for the Slack app and SonarQube Slack is on its Free plan. Linear Slack intake is Business', NULL, '2026-11-19', 0, NULL, 100);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('github', 'GitHub', 'mcp-github', 'Personal account behaves as Free (HTTP 403 on private-repo protection). Freedom-Angel-Corp is on the free plan with 1 seat', 'doc-verified', 'Read-only GitHub API, 2026-11-14', 'connected-working', NULL, 'Everything above', 'Self-hosted runners are free. Private repos cannot enforce merge gates without a paid plan', '2026-11-14', '2026-11-19', 1, 'docs/STACK.md says GitHub Enterprise (Freedom-Angel-Corp). The API reported the free plan with 1 seat.', 110);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('linear', 'Linear', 'mcp-linear', 'Unknown (workspace RisingAloha)', 'unverified', 'Free plan includes integrations, API and MCP', 'connected', 'MCP connected', NULL, 'Free covers 250 issues and 2 teams', NULL, '2026-11-19', 0, NULL, 120);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('zapier', 'Zapier', 'mcp-zapier', 'Unknown', 'unverified', 'Free: 100 tasks a month, two-step Zaps', 'available', 'MCP connected', NULL, 'n8n replaces it once the 100 tasks run out', NULL, '2026-11-19', 0, NULL, 130);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('higgins', 'Higgins', 'higgins', 'Unknown', 'unverified', 'Audrey''s name for an app; the product has not been identified. Another agent guessed Higgsfield, which is a guess', 'unverified', NULL, 'Audrey says she added it next to Gitar with CircleCI API work done', 'None until Audrey names it', NULL, '2026-11-19', 0, NULL, 140);
INSERT INTO connector (id, app, registry_id, plan_tier, tier_source, tier_note, status, status_note, connects_note, free_workaround, verified_on, added_on, stale, stale_note, sort_order) VALUES ('gumloop', 'Gumloop', NULL, 'Unknown', 'unverified', 'docs/standards/RUNNER_TARGETS.md says the operator pays about 60 USD a month for n8n and Gumloop together. That is a repo statement, not checked against a bill', 'unverified', 'Listed as a runner target in the repo', NULL, 'None recorded. RUNNER_TARGETS.md treats it as already-paid capacity', NULL, '2026-11-19', 0, NULL, 150);
